class Solution { public:int countUnguarded(int m,int n,vector<vector<int>>& guards,vector<vector<int>>& walls){vector<vector<int>> state(m,vector<int>(n));for(auto& wall:walls)state[wall[0]][wall[1]]=2;for(auto& guard:guards)state[guard[0]][guard[1]]=3;int directions[5]={1,0,-1,0,1};for(auto& guard:guards)for(int d=0;d<4;++d){int row=guard[0]+directions[d],column=guard[1]+directions[d+1];while(row>=0&&row<m&&column>=0&&column<n&&state[row][column]!=2&&state[row][column]!=3){state[row][column]=1;row+=directions[d];column+=directions[d+1];}}int answer=0;for(auto& row:state)answer+=count(row.begin(),row.end(),0);return answer;} };
